#!/usr/bin/env python3
"""Generate nginx.conf from routes.json, the only route table (#13).

Run after editing routes.json: `python3 infra/gateway/build_nginx.py`.
`backend/tests/test_gateway.py` fails if the committed file is stale.

Anything not listed gets a 404, which is what keeps `/internal/` and `/metrics` private.
"""

import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent

TEMPLATE = """\
# Generated by infra/gateway/build_nginx.py from routes.json. Do not edit.
events {{
    worker_connections 4096;
}}

http {{
    access_log off;
    client_max_body_size 10m;
{resolver}
{upstreams}
    server {{
        listen 8000;

        # The original Host: paginated `next` links are absolute URLs.
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection "";
        proxy_http_version 1.1;
        # A stopped service is a quick 502 rather than a client left waiting.
        proxy_connect_timeout 2s;
        proxy_read_timeout 60s;

{locations}
        location / {{
            default_type application/json;
            return 404 '{{"detail":"Not found."}}';
        }}
    }}
}}
"""

# Docker's DNS. A restarted container can come back on a new address, and nginx would
# otherwise keep the one it resolved at startup.
DOCKER_RESOLVER = """\

    resolver 127.0.0.11 valid=5s;
"""


def _upstream(name: str, address: str, *, resolve: bool) -> str:
    server = f"server {address} resolve;" if resolve else f"server {address};"
    zone = f"        zone {name} 64k;\n" if resolve else ""
    return (
        f"    upstream {name} {{\n{zone}        {server}\n"
        "        keepalive 64;\n    }\n"
    )


def render(table: dict, addresses: dict[str, str] | None = None) -> str:
    """The nginx config. With `addresses`, fixed ones instead of Docker's names."""
    resolve = addresses is None
    upstreams = "".join(
        _upstream(
            name,
            service["upstream"] if resolve else addresses[name],
            resolve=resolve,
        )
        for name, service in table["services"].items()
    )
    locations = "".join(
        f"        location ^~ {route['prefix']} {{\n"
        f"            proxy_pass http://{route['service']};\n"
        "        }\n"
        for route in table["routes"]
    )
    return TEMPLATE.format(
        resolver=DOCKER_RESOLVER if resolve else "",
        upstreams=upstreams,
        locations=locations,
    )


def main() -> None:
    table = json.loads((HERE / "routes.json").read_text())
    # `--address catalog=10.0.0.1:8000 ...` prints a config for fixed addresses (LXC).
    addresses = [arg for arg in sys.argv[1:] if arg != "--address"]
    if addresses:
        print(render(table, dict(item.split("=", 1) for item in addresses)), end="")  # noqa: T201
        return
    (HERE / "nginx.conf").write_text(render(table))


if __name__ == "__main__":
    main()
